  const ck = kind === 'moondock' ? 'moonDock' : kind;
  const cur = kind === 'moondock' ? (location.pathname.match(/^\/moons\/(\d+)/) || [])[1] : isMoon ? moonHere() : curPlanet(), chs = syChoice[ck] || (syChoice[ck] = {});
  if ((kind === 'moon' || kind === 'moondock') && chs[cur] && chs[cur].until && Date.now() > chs[cur].until) { delete chs[cur]; glSave('idleChoice', syChoice); }
  // MO-013: a moon's buttons work whether or not it is building; hidden = our choice or the game's muted reminder. MO-014: dockyard = our choice only
  const st = kind === 'moondock' ? (moonDockHidden(cur) ? 'hidden' : 'idle') : kind === 'moon' ? (moonHidden(cur) || moonState[cur] === 'hidden' ? 'hidden' : 'idle') : (kind === 'research' ? researchState(cur) : idleState[kind][cur]) || '';
  let ch = chs[cur];
