  const pos = cr || onMoonBanner ? 'bottom' : 'top', other = pos === 'bottom' ? 'top' : 'bottom', v = (cr ? Math.max(0, Math.round(hr.bottom - cr.bottom)) : onMoonBanner ? 14 : 8) + 'px';
  if (box.style[pos] !== v) box.style[pos] = v;
  if (box.style[other]) box.style[other] = '';
