NL.feature({
  id: 'gl-menu', set: 'Global', name: 'Left menu',
  desc: 'GL-001: main links without a heading (with Moons and Outposts under Fleet), Other and Dashboards; idle badges; reminder buttons on Shipyard, Buildings and Research.',
  init(ctx) {
    NL.css('gl-menu', `
      body.nl2g-sidenav .sidebar-nav > .sidebar-section:not([data-nx-custom]):not([data-nl2-menu]):not([data-nxl]){display:none!important}
      body.nl2g-nofoot .sidebar-footer{display:none!important}
      .sidebar-nav .sidebar-section-label.nl2g-coll{cursor:pointer;user-select:none;display:flex;align-items:center;justify-content:space-between}
      .sidebar-nav .sidebar-section-label.nl2g-coll:hover{color:#e6f0ff}
      .sidebar-nav .sidebar-section.nl2g-collapsed > :not(.sidebar-section-label){display:none!important}
      .sidebar-nav button.nl2-gamelink,.sidebar-nav button.nl2-grp,.sidebar-nav button.nl2-sub{width:100%;background:none;border:0;font:inherit;color:inherit;text-align:left;cursor:pointer}
      .sidebar-nav .nl2-grp > .nl2-idlebadge{margin-left:auto}
      .sidebar-nav .nl2-sub > .nl2-idlebadge{margin-left:auto}
      .sidebar-nav .nl2-sub{padding-left:46px!important;font-size:.95em}
      .sidebar-nav .nl2-sub.nl2-cur{color:#fbbf24}
      .sidebar-nav a.sidebar-link[href="/fleet"] > .sidebar-badge:not(.nl2-idlebadge){display:none!important}
      .shipyard-page .sy-hero{position:relative}
      .nl2-syopts{position:absolute;right:16px;display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
      .nl2-syopts.nl2-syopts-moon{z-index:2}
      .nl2-syopts.nl2-syopts-moon .nl2-synote{position:absolute;right:0;bottom:100%;margin-bottom:4px}
      .nl2-sybtn{display:inline-flex;align-items:center;box-sizing:border-box;height:30px;padding:0 12px;border-radius:999px;border:1px solid rgba(120,200,255,.35);background:rgba(56,189,248,.10);color:#d9e6f7;font-family:Rajdhani,"Exo 2",sans-serif;font-size:14px;font-weight:600;letter-spacing:.3px;line-height:1;white-space:nowrap;cursor:pointer}
      .nl2-sybtn:hover:not(:disabled){background:rgba(56,189,248,.22);color:#fff}
      .nl2-sybtn.nl2-sysel{background:rgba(251,191,36,.22);border-color:rgba(245,158,11,.6);color:#fbbf24}
      .nl2-synote{align-self:center;color:#fbbf24;font-family:Rajdhani,"Exo 2",sans-serif;font-size:14px;font-weight:600;white-space:nowrap}
      .nl2-sybtn:disabled,.nl2-syopts.nl2-busy .nl2-sybtn{opacity:.45;cursor:default}
      body.nl2g-quietpicker .planet-switcher-dropdown,body.nl2g-quietpicker .qol-idle-panel{visibility:hidden!important;pointer-events:none!important}`);
    // an open Moons or Outposts list closes when another menu item is clicked (David 25 Oct). Registered before the pass-through below,
    // which stops clicks on copied items.
    window.addEventListener('click', (e) => {
      const item = e.target.closest && e.target.closest('.sidebar-nav .sidebar-link');
      if (!item) return;
      const keep = item.dataset.nl2Grp || (item.dataset.nl2Moon ? 'moons' : item.dataset.nl2Outpost ? 'outposts' : '');
      let ch = false;
      for (const k of ['moons', 'outposts']) if (k !== keep && menuOpen[k]) { menuOpen[k] = false; ch = true; }
      if (ch) { glSave('menuOpen', menuOpen); schedule(); }
    }, true);
    // a click on a copied item is stopped before the game sees it and passed to the game's own item (one click sound, not two)
    window.addEventListener('click', (e) => {
      const el = e.target.closest && e.target.closest('.sidebar-nav .nl2-mirror, .sidebar-nav button.nl2-gamelink');
      if (!el) return;
      if (el.tagName === 'A' && (e.button || e.ctrlKey || e.metaKey || e.shiftKey)) return;   // new-tab clicks keep the copied href
      let orig;
      if (el.classList.contains('nl2-gamelink')) orig = footerItems().find((x) => labelOf(x) === el.dataset.nl2Game);
      else { const links = gameLinks(); orig = (el.dataset.nl2Path && links.find((a) => pathOf(a) === el.dataset.nl2Path)) || links.find((a) => labelOf(a) === el.dataset.nl2Src); }
      if (!orig) return;
      e.preventDefault();
      e.stopImmediatePropagation();
      quietClick(orig);
    }, true);
    document.addEventListener('click', (e) => {
      const g = e.target.closest && e.target.closest('.sidebar-nav .nl2-grp, .sidebar-nav .nl2-sub');
      if (g) {
        e.preventDefault();
        if (g.dataset.nl2Grp) { menuOpen[g.dataset.nl2Grp] = !menuOpen[g.dataset.nl2Grp]; glSave('menuOpen', menuOpen); schedule(); }
        else if (g.dataset.nl2Moon) openMoon(g.dataset.nl2Moon);
        else if (g.dataset.nl2Outpost) openOutpost(g.dataset.nl2Outpost);
        return;
      }
      const label = e.target.closest && e.target.closest('.sidebar-nav > .sidebar-section > .sidebar-section-label');
      if (!label) return;
      const key = keyOf(label.parentElement);
      if (!key) return;
      collapsed = glLoad('collapsed', {});              // another tab may have changed it
      if (collapsed[key]) delete collapsed[key]; else collapsed[key] = true;
      glSave('collapsed', collapsed);
      applyCollapse(label.closest('.sidebar-nav'));
    });
    window.addEventListener('storage', (e) => { if (e.key === GL_KEY('collapsed')) { collapsed = glLoad('collapsed', {}); schedule(); } });
    try { const pend = sessionStorage.getItem('nl2MoonTab'); if (pend) { sessionStorage.removeItem('nl2MoonTab'); const v = pend[0] === '{' ? JSON.parse(pend) : { path: pend }; moonTab(v.path, v.tab); } } catch (e) { /* */ }
    try { const pend = sessionStorage.getItem('nl2Outpost'); if (pend) { sessionStorage.removeItem('nl2Outpost'); if (location.pathname === '/mining') openOutpost(pend, 1); } } catch (e) { /* */ }

    NL.onData(/^\/api\/outposts(\?|$)/, (p, d) => setOutposts(d));
    NL.onData(/^\/api\/planets\/activity-summary(\?|$)/, (p, d) => gotActivity(d));
    window.addEventListener('nl2:moondock', () => schedule());   // SH-003: a Moon Dockyard level seen or changed
    if (NL.buStorage) NL.buStorage.onChange(() => schedule());    // BU-010: storage data or threshold changed
    NL.onData(/^\/api\/planets\/\d+(\?|$)/, (p, d) => gotPlanet(d));
    NL.onData(/^\/api\/planets\/\d+\/shipyard(\?|$)/, (p, d) => gotYardShips(d));
    if (!outposts.at || Date.now() - outposts.at > 15 * 60 * 1000) NL.getJson('/api/outposts', ctx);      // the tee stores the reply

    // the picker: read it when David opens it, at start, and every 2 minutes (G-060)
    const seenDd = new WeakSet();
    let started = false;
    NL.watch('.planet-switcher-dropdown', (d) => {
      if (pickerBusy || seenDd.has(d)) return;
      seenDd.add(d);
      scrapePicker(false);
      setTimeout(() => { if (pickerDd() === d && !pickerBusy && Date.now() - lastRefresh > 1500) scrapePicker(true); }, 1500);
    });
    NL.watch('.planet-switcher-btn', () => {
      if (started) return;
      started = true;
      if (Date.now() - idle.at > 60000) setTimeout(refreshIdle, 1500);
      setInterval(() => {      // David's chosen 2-minute refresh (G-060)
        const a = document.activeElement;
        if (document.visibilityState === 'visible' && !pickerDd() && !pickerBusy && Date.now() - lastRefresh >= 60000
          && !(a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName))) refreshIdle();
      }, 120000);
    });
    NL.watch('.sidebar-nav', menuTick);
    NL.watch('.game-content', ensureReminderBtns);
    // MO-014: moon tabs and Fleet sub-sections only move .active (no node changes), so re-check the moon reminder box on their clicks
    document.addEventListener('click', (e) => { if (e.target.closest && e.target.closest('nav.moon-workspace-tabs, [id="moon-view-fleet"]')) { setTimeout(schedule, 50); setTimeout(schedule, 300); } }, true);
  },
});

// ================================================================ GL-002 header
// Every banner item becomes one uniform pill (the game's element, restyled); a Mute button after the server clock; ranking pills right of
// the planet selector; the clock loses its "Server time" words. The picker lists planets only, plus the moon you are on while you are on it.
const PILL_LABELS = { 'Audio controls': 'Audio', 'Report a bug': 'Report Bug', 'Store': 'Store' };
function pillify() {
  const tb = document.querySelector('.topbar');
  if (!tb) return;
  for (const g of tb.querySelectorAll('.topbar-left > *, .topbar-right > *')) {
    if (g.matches('.hamburger-btn, .nl2-mute, .nl2-ranks, .nl2-fslots, .nl2g-icon, .nl2-options, .nl2-optbg, .nl2-optcustom')) continue;
    const el = g.matches('a, button') ? g : g.querySelector('a, button');
    if (!el) { if (!g.classList.contains('nl2g-plain')) g.classList.add('nl2g-plain'); continue; }
    const text = (el.innerText || '').replace(/\s+/g, ' ').trim();
    let label = '';
    if (!text && !el.classList.contains('nl2g-hastext')) {
      const t = el.getAttribute('title') || el.getAttribute('aria-label') || g.getAttribute('title') || g.getAttribute('aria-label') || '';
      label = PILL_LABELS[t] || '';
      if (!label) { g.classList.add('nl2g-icon'); continue; }      // an icon-only button we don't know (an event button) stays the game's icon
    }
    if (g !== el && !g.classList.contains('nl2g-pillwrap')) g.classList.add('nl2g-pillwrap');
    if (!el.classList.contains('nl2g-pill')) el.classList.add('nl2g-pill');
    if (label && el.dataset.nl2Label !== label) el.dataset.nl2Label = label;
    if ((text || label) && !el.classList.contains('nl2g-hastext')) el.classList.add('nl2g-hastext');
  }
}
// Mute: works the game's own Mute inside its Audio panel (opened out of sight); the icon follows the game's saved setting
const GAME_MUTE_KEY = 'nexus.music.muted';           // the game's own setting: "1" muted
const gameMuted = () => { try { return localStorage.getItem(GAME_MUTE_KEY) === '1'; } catch (e) { return false; } };
let muteBusy = false, muteBtn = null;
const panelMuteBtn = () => { const panel = document.querySelector('.music-control-panel'); return panel && [...panel.querySelectorAll('.music-mini-btn')].find((b) => /^(un)?mute$/i.test((b.textContent || '').trim())); };
async function toggleGameMute() {
  const audioBtn = document.querySelector('.topbar .music-control-btn');
  if (muteBusy || !audioBtn) return;
  muteBusy = true;
  document.body.classList.add('nl2g-hidepanel');
  const wasOpen = !!document.querySelector('.music-control-panel');
  try {
    if (!wasOpen) quietClick(audioBtn);
    let btn = null;
    for (let i = 0; i < 20 && !(btn = panelMuteBtn()); i++) await sleep(50);
    if (btn) quietClick(btn);
    // GL-010: the panel may close by itself, a moment late, after Mute; only close it ourselves if it is still open after 300 ms,
    // and keep it hidden until it is really gone, so a late close can't be undone by our own click
    const panelOpen = () => !!document.querySelector('.music-control-panel');
    for (let i = 0; !wasOpen && i < 6 && panelOpen(); i++) await sleep(50);
    if (!wasOpen && panelOpen()) quietClick(audioBtn);
    for (let i = 0; !wasOpen && i < 20 && panelOpen(); i++) await sleep(50);
  } finally {
    document.body.classList.remove('nl2g-hidepanel');
    muteBusy = false;
    updateMuteBtn();
  }
}
const SPEAKER = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="currentColor"></polygon>'
  + '<path class="nl2-wave" d="M15.5 8.5a5 5 0 0 1 0 7"></path><path class="nl2-wave" d="M18.5 5.5a9 9 0 0 1 0 13"></path>'
  + '<line class="nl2-slash" x1="2" y1="2" x2="22" y2="22"></line></svg>';
function updateMuteBtn() {
  if (!muteBtn) return;
  const muted = gameMuted(), t = muted ? 'Game is muted: click to unmute' : 'Mute the game';
  if (muteBtn.classList.contains('nl2-muted') !== muted) muteBtn.classList.toggle('nl2-muted', muted);
  if (muteBtn.title !== t) { muteBtn.title = t; muteBtn.setAttribute('aria-label', t); }
  if (muteBtn.getAttribute('aria-pressed') !== String(muted)) muteBtn.setAttribute('aria-pressed', String(muted));
}
function ensureMuteBtn() {
  const audio = document.querySelector('.topbar .music-control') || document.querySelector('.topbar [title="Audio controls"]');
  if (!audio) return;
  if (!muteBtn) {
    muteBtn = NL.h('button', { type: 'button', class: 'nl2-mute' });
    muteBtn.innerHTML = SPEAKER;
    muteBtn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); toggleGameMute(); });
  }
  const after = document.querySelector('.topbar .topbar-server-clock') || audio;      // Mute sits right after the server clock
  if (after.nextElementSibling !== muteBtn) after.after(muteBtn);
  updateMuteBtn();
}
// Rankings: one pill each, name and rank, score in the hover; click opens that ranking's tab
const RANKS = [['overall', 'Overall', '#facc15'], ['military', 'Military', '#f87171'], ['economy', 'Economy', '#4ade80'], ['research', 'Research', '#c084fc']];
let rankData = null, rankAt = 0, rankBox = null;
{ const st = glLoad('rankData', null, 'nxgRankData'); if (st && st.rank) { rankData = st.rank; rankAt = st.at || 0; } }
function setRank(j) {
  if (!j || !j.rank) return;
  rankData = j.rank; rankAt = Date.now();
  glSave('rankData', { rank: rankData, at: rankAt });
  renderRanks();
}
function renderRanks() {
  if (!rankBox || !rankData) return;
  const html = RANKS.filter(([k]) => rankData[k + 'Rank'] != null).map(([k, name, col]) => {
    const rank = rankData[k + 'Rank'], score = Number(rankData[k + 'Score']) || 0;
    return `<a class="nl2-rank" href="/rankings" data-nl2-tab="${name}" style="--nl2-c:${col}" title="${name}: rank #${rank}, score ${score.toLocaleString()}">${name} #${rank}</a>`;
  }).join('');
  if (rankBox.innerHTML !== html) rankBox.innerHTML = html;
  const when = (rankData.lastCalculatedAt ? 'Rankings last calculated ' + new Date(rankData.lastCalculatedAt).toLocaleString() + '. ' : '') + 'As of ' + new Date(rankAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  if (rankBox.title !== when) rankBox.title = when;
}
function clickRankingTab(name, tries = 0) {
  const tab = [...document.querySelectorAll('.rankings-tab')].find((b) => (b.textContent || '').trim() === name);
  if (tab) { if (!tab.classList.contains('active')) quietClick(tab); return; }
  if (tries < 50) setTimeout(() => clickRankingTab(name, tries + 1), 100);   // the page draws its tabs after its data loads
}
function openRankingTab(name) {
  if (location.pathname !== '/rankings' || location.hash) {
    if (!routerPush('/rankings')) { try { sessionStorage.setItem('nl2RankTab', name); } catch (e) { /* */ } location.href = '/rankings'; return; }
  }
  clickRankingTab(name);
}
function ensureRanks() {
  const ps = document.querySelector('.topbar .planet-switcher');
  if (!ps) return;
  if (!rankBox) {
    rankBox = NL.h('div', { class: 'nl2-ranks' });
    rankBox.addEventListener('click', (e) => {
      const a = e.target.closest('a.nl2-rank');
      if (!a || e.button || e.ctrlKey || e.metaKey || e.shiftKey) return;   // new-tab clicks just open Rankings
      e.preventDefault();
      openRankingTab(a.dataset.nl2Tab);
    });
    renderRanks();
  }
  if (ps.nextElementSibling !== rankBox) ps.after(rankBox);
}
// GL-002: the picker hides moons except the one you are on (only while you are on it)
function markCurMoon() {
  const d = pickerDd();
  if (!d) return;
  const cur = curPlanet();
  for (const it of d.querySelectorAll('.ps-moon-item')) {
    const on = cleanName((it.querySelector('.ps-item-name') || it).textContent) === cur;
    if (it.classList.contains('nl2g-curmoon') !== on) it.classList.toggle('nl2g-curmoon', on);
  }
}

