// ================================================================ GL-003 Options
// Language, player name, Command Core, Audio, Report Bug, Store and the type item are the game's own controls. They stay where the game put
// them (so its popups keep working) but are hidden until Options is open; then they stack down the right side on one solid panel, with our
// Custom section (feature settings and switches) at the bottom.
const OPT_SEL = ['.lang-selector', '.topbar-user', 'a.topbar-command-core', '.music-control', '.topbar-bug-btn', '.topbar-store-btn', '.topbar-leader-wrapper, .topbar-race'];
const POP_SEL = '.music-control-panel, [role="menu"], [role="listbox"], [role="dialog"], [class*="dropdown"], [class*="popover"], [class*="menu"]';
const OPT_W = 230, OPT_BG = '#0b1220';
let optBtn = null, optBg = null, optCustom = null, optOpen = false;
function optItems() {
  const tr = document.querySelector('.topbar-right');
  if (!tr) return [];
  const out = [];
  OPT_SEL.forEach((sel, i) => {
    const m = tr.querySelector(sel);
    if (!m) return;
    let g = m;
    while (g.parentElement && g.parentElement !== tr) g = g.parentElement;
    if (g.parentElement === tr && !out.some((x) => x[1] === g)) out.push([i, g]);
  });
  return out;
}
function closeOpt() {
  if (!optOpen) return;
  optOpen = false;
  document.body.classList.remove('nl2g-optopen');
  if (optBtn) optBtn.setAttribute('aria-expanded', 'false');
}
function layoutOptions() {
  const tb = document.querySelector('.topbar');
  if (!optOpen || !tb) return;
  const left = Math.max(8, innerWidth - OPT_W - 14);
  const items = optItems(), bar = tb.getBoundingClientRect(), top0 = Math.round(bar.bottom) + 8;
  document.body.style.setProperty('--nl2-ol', left + 'px');
  let top = top0;
  for (const [, g] of items) { g.style.setProperty('--nl2-ot', top + 'px'); top += (g.offsetHeight || 30) + 6; }
  let dx = 0, dy = 0;
  if (items.length) {       // a transformed ancestor moves "fixed" rows: measure where the first row really is and shift everything by the error
    const r = items[0][1].getBoundingClientRect();
    dx = r.left - left; dy = r.top - top0;
    if (Math.abs(dx) > 1) document.body.style.setProperty('--nl2-ol', (left - dx) + 'px'); else dx = 0;
    if (Math.abs(dy) > 1) for (const [, g] of items) g.style.setProperty('--nl2-ot', (parseFloat(g.style.getPropertyValue('--nl2-ot')) - dy) + 'px'); else dy = 0;
  }
  const l = left - dx, t0 = top0 - dy;
  if (optCustom) { optCustom.style.left = l + 'px'; optCustom.style.top = (top - dy) + 'px'; optCustom.style.width = OPT_W + 'px'; }
  const ch = optCustom ? optCustom.offsetHeight : 0;
  if (optBg) { optBg.style.left = (l - 8) + 'px'; optBg.style.top = (t0 - 8) + 'px'; optBg.style.width = (OPT_W + 16) + 'px'; optBg.style.height = (top - top0 + ch + 10) + 'px'; }
}
function ensureOptions() {
  const anchor = (muteBtn && muteBtn.isConnected && muteBtn) || document.querySelector('.topbar .topbar-server-clock');
  if (!anchor) return;
  for (const [i, g] of optItems()) { if (!g.classList.contains('nl2g-opt')) g.classList.add('nl2g-opt'); if (g.dataset.nl2Opt !== String(i)) g.dataset.nl2Opt = String(i); }
  if (!optBtn) {
    optBtn = NL.h('button', { type: 'button', class: 'nl2-options', 'aria-expanded': 'false' }, 'Options ▾');
    optBtn.addEventListener('click', (e) => {
      e.preventDefault(); e.stopPropagation();
      optOpen = !optOpen;
      document.body.classList.toggle('nl2g-optopen', optOpen);
      optBtn.setAttribute('aria-expanded', String(optOpen));
      if (optOpen) layoutOptions();
    });
    optBg = NL.h('div', { class: 'nl2-optbg' });
    optCustom = NL.h('button', { type: 'button', class: 'nl2-optcustom', title: 'Settings for our own features' }, 'Custom');
    optCustom.addEventListener('click', (e) => { e.preventDefault(); closeOpt(); NL.openSettings(); });
    window.addEventListener('resize', layoutOptions);
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeOpt(); });
    document.addEventListener('click', (e) => {
      if (!optOpen || e.target.closest('.nl2-options')) return;
      const row = e.target.closest('.nl2g-opt');
      if (row) {
        // a click on the row's empty space works the row's own control, as if its text was clicked (David 25 Oct)
        const ctl = row.matches('a, button') ? row : row.querySelector('a, button');
        if (ctl && !e.target.closest('a, button, input, select, textarea')) { e.preventDefault(); e.stopPropagation(); quietClick(ctl); return; }
        if (/^[1245]$/.test(row.dataset.nl2Opt || '')) setTimeout(closeOpt, 0);   // links and dialogs close it; Language, Audio and type stay
        return;
      }
      if (e.target.closest('.nl2-optbg, .nl2-optcustom') || e.target.closest(POP_SEL)) return;
      closeOpt();
    }, true);
  }
  if (anchor.nextElementSibling !== optBtn) anchor.after(optBtn);
  const trow = document.querySelector('.topbar-right');
  // NOT on body: the banner is its own layer (z 900) and would cover the rows under a body-level panel (G-068)
  if (trow && optBg.parentElement !== trow) trow.appendChild(optBg);
  if (trow && optCustom.parentElement !== trow) trow.appendChild(optCustom);
  if (optOpen) layoutOptions();
}

NL.feature({
  id: 'gl-options', set: 'Global', name: 'Options menu',
  desc: 'GL-003: the game\'s option items under one Options button on a solid panel, with a Custom section for our settings.',
  init() {
    NL.css('gl-options', `
      .topbar .nl2-options{display:inline-flex;align-items:center;box-sizing:border-box;height:30px;padding:0 12px;border-radius:999px;border:1px solid rgba(120,200,255,.35);background:rgba(56,189,248,.10);color:#d9e6f7;font-family:Rajdhani,"Exo 2",sans-serif;font-size:14px;font-weight:600;letter-spacing:.3px;line-height:1;white-space:nowrap;cursor:pointer}
      .topbar .nl2-options:hover,body.nl2g-optopen .topbar .nl2-options{background:rgba(56,189,248,.22);color:#fff}
      .topbar .nl2g-opt{display:none!important}
      .nl2-optbg,.nl2-optcustom{display:none;position:fixed;box-sizing:border-box}
      .nl2-optbg{z-index:2147482999;border-radius:12px;border:1px solid rgba(120,200,255,.35);background:${OPT_BG};box-shadow:0 8px 24px rgba(0,0,0,.5)}
      body.nl2g-optopen .nl2-optbg,body.nl2g-optopen .nl2-optcustom{display:block}
      .nl2-optcustom{z-index:2147483000;display:none;height:30px;padding:0 12px;text-align:left;background:${OPT_BG};color:#fff;font-family:Rajdhani,"Exo 2",sans-serif;font-size:14px;font-weight:600;letter-spacing:.3px;border:0;border-top:1px solid rgba(120,200,255,.25);cursor:pointer}
      .nl2-optcustom:hover{background:#1b2536}
      body.nl2g-optopen .topbar .nl2g-opt{display:flex!important;position:fixed!important;left:var(--nl2-ol)!important;top:var(--nl2-ot)!important;right:auto!important;bottom:auto!important;width:${OPT_W}px!important;margin:0!important;transform:none!important;z-index:2147483000!important;box-sizing:border-box!important;justify-content:flex-start!important}
      /* GL-003: solid rows. Each row is painted the panel colour and a shadow fills the 6 px gap under it, so the menu is solid even if the panel is out of place */
      body.nl2g-optopen .topbar .nl2g-opt{background:${OPT_BG}!important;background-image:none!important;backdrop-filter:none!important;opacity:1!important;border-color:transparent!important;box-shadow:0 6px 0 0 ${OPT_BG}!important;color:#fff!important}
      body.nl2g-optopen .topbar .nl2g-opt .nl2g-pill{background:transparent!important;background-image:none!important;backdrop-filter:none!important;border-color:transparent!important;box-shadow:none!important;color:#fff!important;width:100%!important;justify-content:flex-start!important}
      body.nl2g-optopen .topbar .nl2g-opt *{color:#fff!important}
      body.nl2g-optopen .topbar .nl2g-opt:hover,body.nl2g-optopen .topbar .nl2g-opt .nl2g-pill:hover{background:#1b2536!important}
      body.nl2g-optopen .topbar a.topbar-command-core.nl2g-pill{height:30px!important;padding:0 12px!important;overflow:visible!important}
      body.nl2g-optopen .topbar a.topbar-command-core.nl2g-pill .topbar-command-core-art{display:none!important}
      body.nl2g-optopen .topbar a.topbar-command-core.nl2g-pill .topbar-command-core-label{display:inline!important}`);
    NL.watch('.topbar', ensureOptions);
  },
});

// ================================================================ GL-012: why the game's Dispatch is greyed (read live 27 Oct, nexus_tests/bring_cargo_dom_27oct.md)
// The dispatch page's cargo inputs carry the source planet's stock as max; the capacity bar reads "loaded / capacity". When something
// stops the send we say what, in red above Dispatch Fleet: cargo above stock, cargo above the ships' capacity, or no ships chosen.
const glNum = (t) => Number(String(t || '').replace(/[^\d.]/g, '')) || 0;
function dispatchReasons(ws) {
  const out = [], src = ws.querySelector('.location-select .location-select-row-label');
  const from = src ? src.textContent.trim() : 'this planet';
  for (const g of ws.querySelectorAll('.gift-cargo-grid .form-group')) {
    const i = g.querySelector('input[type=number]'), name = (g.querySelector('.gift-cargo-label span') || {}).textContent || 'cargo';
    if (!i || i.max === '' || !i.value) continue;
    const v = Number(i.value), max = Number(i.max);
    if (v > max) out.push(`Not enough ${name.trim()} on ${from}: needs ${v.toLocaleString('en-US')}, has ${max.toLocaleString('en-US')}`);
  }
  const cap = ws.querySelector('.cargo-capacity-label span'), m = cap && cap.textContent.match(/([\d,]+)\s*\/\s*([\d,]+)/);
  if (m && glNum(m[1]) > glNum(m[2])) out.push(`Cargo ${m[1]} is more than the ships carry (${m[2]}): add ships or lower the cargo`);
  const ships = [...ws.querySelectorAll('.ship-select-row input[type=number]')];
  if (ships.length && ships.every((i) => !Number(i.value))) out.push('No ships chosen');
  return out;
}
function ensureDispatchReason(ws) {
  const btn = ws.querySelector('.dispatch-btn');
  if (!btn) return;
  if (!ws.dataset.nl2Reason) { ws.dataset.nl2Reason = '1'; ws.addEventListener('input', () => setTimeout(NL._kick, 0)); ws.addEventListener('click', () => setTimeout(NL._kick, 0)); }
  let line = ws.querySelector('.nl2-dispreason');
  const why = btn.disabled ? dispatchReasons(ws) : [];
  if (!why.length) { if (line) line.remove(); return; }
  if (!line) line = NL.h('div', { class: 'nl2-dispreason' });
  if (line.nextElementSibling !== btn) btn.before(line);
  const t = why.join('\n');
  if (line.textContent !== t) line.textContent = t;
}
NL.feature({
  id: 'gl-dispreason', set: 'Global', name: 'Dispatch reason',
  desc: 'GL-012: on the Fleet dispatch page, a red line above Dispatch Fleet says why it is greyed (cargo above stock or ship capacity, no ships).',
  init() {
    NL.css('gl-dispreason', '.nl2-dispreason{color:#f87171;font-size:14px;font-weight:600;line-height:1.35;margin:0 0 8px;white-space:pre-line}');
    NL.watch('.command-dispatch-workspace', ensureDispatchReason);
  },
});

// ================================================================ GL-013: Fit ships on a Market Hub's Pickup dialog (read live 27 Oct, nexus_tests/hub_pickup_dom_27oct.md)
// The game's own dialog: ship rows (.hub-pickup-ship-row, "Cargo: N" per ship, qty input), and once ships are chosen the cargo rows
// (.hub-pickup-resource-row, input max = what the hub holds). Fit ships sets the ship inputs to the fewest transports for the cargo
// entered, with the Collection fit (game's own when loaded). No cargo entered yet: it first takes everything (all ships, then each Max).
// We only fill the game's inputs; David presses the game's Pickup.
const HUB_SHIP_KEYS = { 'transport shuttle': 'transport_shuttle', 'bulk carrier': 'bulk_carrier', freighter: 'freighter', tanker: 'tanker' };
const setInput = (i, v) => { Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(i, String(v)); i.dispatchEvent(new Event('input', { bubbles: true })); i.dispatchEvent(new Event('change', { bubbles: true })); };
async function hubFit(modal, note) {
  const shipRows = () => [...modal.querySelectorAll('.hub-pickup-ship-row')].map((r) => ({ r, i: r.querySelector('input[type=number]'),
    name: ((r.querySelector('.ship-select-copy span') || r.querySelector('.ship-select-name') || {}).textContent || '').trim(), cargo: glNum((r.querySelector('.hub-pickup-cargo') || {}).textContent) })).filter((x) => x.i);
  const resRows = () => [...modal.querySelectorAll('.hub-pickup-resource-row')].map((r) => ({ r, i: r.querySelector('input[type=number]'), name: ((r.querySelector('.ship-select-name') || {}).textContent || '').trim() })).filter((x) => x.i);
  const total = () => resRows().reduce((t, x) => t + (Number(x.i.value) || 0), 0);
  note.textContent = '';
  if (!total()) {                                    // nothing chosen yet: all ships so every Max takes the lot, then fit down
    for (const s of shipRows()) setInput(s.i, s.i.max || 0);
    for (let k = 0; k < 20 && !resRows().length; k++) await sleep(100);
    for (const x of resRows()) { const b = x.r.querySelector('.spy-max-btn'); if (b && !b.disabled) b.click(); }
    await sleep(200);
  }
  const need = {};
  for (const x of resRows()) { const v = Number(x.i.value) || 0; if (v > 0) need[x.name.toLowerCase().replace(/\s+/g, '_')] = v; }
  const sum = Object.values(need).reduce((a, b) => a + b, 0);
  if (!sum) { note.textContent = 'Nothing to pick up'; return; }
  const ships = shipRows().map((s, n) => ({ id: n + 1, key: HUB_SHIP_KEYS[s.name.toLowerCase()] || 'freighter', available: Number(s.i.max) || 0, cargo: s.cargo, s }));
  const r = await NL.fleet.fitShips(ships.map(({ s, ...x }) => x), need);
  // raise the chosen types before lowering the rest, so the capacity never drops under the cargo on the way
  const order = ships.slice().sort((a, b) => ((Number(r.ships[b.id]) || 0) > Number(b.s.i.value) ? 1 : 0) - ((Number(r.ships[a.id]) || 0) > Number(a.s.i.value) ? 1 : 0));
  for (const x of order) setInput(x.s.i, Number(r.ships[x.id]) || 0);
  const cap = ships.reduce((t, x) => t + (Number(r.ships[x.id]) || 0) * x.cargo, 0);
  if (!r.complete || cap < sum) note.textContent = 'Short ' + Math.max(0, sum - cap).toLocaleString('en-US') + ' cargo';
}
function ensureHubFit(modal) {
  const foot = modal.querySelector('.spy-modal-footer');
  if (!foot || foot.querySelector('.nl2-hubfit')) return;
  const note = NL.h('span', { class: 'nl2-hubfit-note' });
  const b = NL.h('button', { type: 'button', class: 'nl2-hubfit nl2-c-blue' }, 'Fit ships');
  b.addEventListener('click', async (e) => { e.preventDefault(); e.stopPropagation(); b.disabled = true; try { await hubFit(modal, note); } finally { b.disabled = false; } });
  foot.prepend(b, note);
}
NL.feature({
  id: 'gl-hubfit', set: 'Global', name: 'Hub pickup fit',
  desc: 'GL-013: a Fit ships button on a Market Hub\'s Pickup dialog sets the fewest transports for the chosen cargo (or for everything, if none chosen).',
  init() {
    NL.css('gl-hubfit', '.hub-pickup-modal .nl2-hubfit{margin-right:auto;padding:6px 14px;border-radius:6px;font:inherit;font-weight:600;cursor:pointer}.hub-pickup-modal .nl2-hubfit-note{color:#f87171;font-weight:600;margin-right:8px;align-self:center}');
    NL.watch('.hub-pickup-modal', ensureHubFit);
  },
});

