// ================================================================ GL-016: inbound fleets strip on a planet's Buildings, Shipyard and Research (David 29 Oct, defaults)
// Read live 29 Oct (read-only): GET /api/fleet/missions {missions[], maxFleetSlots}; none of the three pages reads it, so we use the
// teed reply when under a minute old, else one read of our own on opening, and one more just after each listed fleet lands. Mission:
// missionType ('deliver', 'transfer', 'mine', ...), status ('outbound', 'returning', ...), sourcePlanetId/Name, sourceMoonId,
// sourceOutpostId, targetPlanetId/Name, targetMoonId, arrivesAt, returnArrivesAt, cargo { ore: 14291, ... , _private: ... }.
// Inbound = outbound deliver/transfer to this planet (not its moon), or returning home to this planet, carrying cargo. Planets only.
// Heroes: .buildings-page > .bld-hero, .shipyard-page > .sy-hero, .research-page > .res-hero; icons /images/resources/<key>.webp.
// MO-015 (David 31 Oct, defaults): moons too. On every moon tab the game's 'Active Missions (n)' section (.moon-page > section.moon-overview-missions)
// is hidden and the strip sits under the moon banner (.moon-page > .entity-hero): deliveries/transfers to this moon (targetMoonId), and fleets
// returning home to it (sourceMoonId). Same data rules and switch.
const IN_HEROES = '.buildings-page > .bld-hero, .shipyard-page > .sy-hero, .research-page > .res-hero, .moon-page > .entity-hero';
const IN_RES = ['ore', 'silicates', 'hydrogen', 'alloys', 'cryo_ice', 'quantum_dust', 'plasma_core', 'bio_extract', 'dark_matter', 'antimatter'];
const IN_PRIME = ['ore', 'silicates', 'hydrogen', 'alloys'];
const IN_NAME = { ore: 'Ore', silicates: 'Silicates', hydrogen: 'Hydrogen', alloys: 'Alloys', cryo_ice: 'Cryo-Ice', quantum_dust: 'Quantum Dust', plasma_core: 'Plasma Core', bio_extract: 'Bio-Extract', dark_matter: 'Dark Matter', antimatter: 'Antimatter' };
let inData = null, inKey = '', inReading = false, inLandTimer = 0, inLandAt = 0, inTickTimer = 0;
const inShort = (n) => (n < 10000 ? Math.round(n).toLocaleString('en-US') : n < 1e6 ? +(n / 1e3).toPrecision(3) + 'K' : +(n / 1e6).toPrecision(3) + 'M');
const inTs = (v) => { const t = v ? Date.parse(v) : NaN; return Number.isFinite(t) ? t : 0; };
function inCargo(c) {
  const out = {};
  for (const [k, v] of Object.entries(c || {})) {
    if (k[0] === '_' || !(Number(v) > 0)) continue;
    const key = k.replace(/[A-Z]/g, (x) => '_' + x.toLowerCase());
    out[key] = (out[key] || 0) + Number(v);
  }
  return out;
}
function inRows(pid, pname, mid) {
  const now = Date.now(), rows = [];
  for (const m of (inData && inData.missions) || []) {
    if (!m) continue;
    const cargo = inCargo(m.cargo);
    if (!Object.keys(cargo).length) continue;
    const toMoon = mid != null && +m.targetMoonId === +mid, homeMoon = mid != null && +m.sourceMoonId === +mid;
    const toHere = pid != null ? +m.targetPlanetId === +pid : m.targetPlanetName === pname, homeHere = pid != null ? +m.sourcePlanetId === +pid : m.sourcePlanetName === pname;
    let at = 0, label = '', status = '';
    const type = String(m.missionType || '').replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
    if (m.status === 'outbound' && (m.missionType === 'deliver' || m.missionType === 'transfer') && (mid != null ? toMoon : toHere && m.targetMoonId == null)) {
      const moon = m.sourceMoonId != null ? Object.keys(moonIds).find((n) => +moonIds[n] === +m.sourceMoonId) : '';
      const from = moon || (m.sourceMoonId == null && m.sourceOutpostId == null ? m.sourcePlanetName : '') || (m.sourceOutpostId != null ? 'an outpost' : m.sourceMoonId != null ? 'a moon' : '');
      at = inTs(m.arrivesAt); label = type; status = from ? 'from ' + from : '';
    } else if (m.status === 'returning' && (mid != null ? homeMoon : homeHere && m.sourceMoonId == null && m.sourceOutpostId == null)) {
      at = inTs(m.returnArrivesAt) || inTs(m.arrivesAt); label = type; status = 'Returning';
    } else continue;
    if (at && at < now - 5000) continue;
    rows.push({ id: m.id, at, label, status, cargo });
  }
  return rows.sort((a, b) => (a.at || Infinity) - (b.at || Infinity));
}
function inCargoHtml(cargo) {
  return IN_RES.concat(Object.keys(cargo).filter((k) => !IN_RES.includes(k))).filter((k) => cargo[k] > 0).map((k) => {
    const nm = IN_NAME[k] || k.replace(/_/g, ' ');
    return '<span class="nl2-in-res" data-nl2-tip="' + glEsc(nm + ' ' + Math.round(cargo[k]).toLocaleString('en-US')) + '">'
      + (IN_NAME[k] ? '<img class="game-resource-icon" src="/images/resources/' + k + '.webp" alt="">' : '') + glEsc(nm) + ' ' + inShort(cargo[k]) + '</span>';
  }).join('');
}
async function inRead() {
  if (inReading) return;
  inReading = true;
  try { await NL.getJson('/api/fleet/missions'); } finally { inReading = false; }     // our read passes the tee, so onData stores it
}
function ensureInbound(hero) {
  const mm = hero.parentElement.classList.contains('moon-page') && location.pathname.match(/^\/moons\/(\d+)/), mid = mm ? Number(mm[1]) : null;
  const cur = mid != null ? moonHere() || curPlanet() : curPlanet(), p = mid == null && actPlanets.find((x) => x.name === cur), pid = p ? p.id : null;
  let strip = hero.parentElement.querySelector(':scope > .nl2-inbound');
  if (!cur || (mid == null && onMoon())) { if (strip) strip.remove(); return; }
  const key = location.pathname + '|' + cur;
  if (key !== inKey) {                                  // page opened or planet switched: fresh enough teed data, else one read
    inKey = key;
    const c = NL.cache.latest(/^\/api\/fleet\/missions(\?|$)/);
    if (c && Date.now() - c.at < 60000) inData = c.data; else inRead();
  }
  const rows = inRows(pid, cur, mid);
  const next = rows.reduce((t, r) => (r.at && r.at > Date.now() && (!t || r.at < t) ? r.at : t), 0);
  if (next !== inLandAt) { clearTimeout(inLandTimer); inLandAt = next; if (next) inLandTimer = setTimeout(() => { inLandAt = 0; if (document.querySelector(IN_HEROES)) inRead(); }, next - Date.now() + 3000); }
  if (!rows.length) { if (strip) strip.remove(); return; }
  if (!strip) strip = NL.h('div', { class: 'nl2-inbound' });
  if (strip.previousElementSibling !== hero) hero.after(strip);
  // GL-021 (David 1 Nov): a table. Mission, Status, In, the four primary resources, then all rares in one column (each listed)
  // GL-027 (David 2 Nov): no heading or header row, no Arrives column; In counts down in minutes and seconds; icons beside each number
  const inT = (at) => { if (!at) return ''; const s = Math.max(0, Math.round((at - Date.now()) / 1000)); return Math.floor(s / 60) + 'm ' + String(s % 60).padStart(2, '0') + 's'; };
  const num = (c, k) => '<div class="nl2-in-n"' + (c[k] > 0 ? ' data-nl2-tip="' + glEsc(IN_NAME[k] + ' ' + Math.round(c[k]).toLocaleString('en-US')) + '"><img class="game-resource-icon" src="/images/resources/' + k + '.webp" alt="">' + inShort(c[k]) : ' data-e="1">—') + '</div>';
  const rares = (c) => { const ks = Object.keys(c).filter((k) => !IN_PRIME.includes(k) && c[k] > 0); return ks.length ? '<div class="nl2-in-rare">' + inCargoHtml(Object.fromEntries(ks.map((k) => [k, c[k]]))) + '</div>' : '<div data-e="1">—</div>'; };
  const cells = (c) => IN_PRIME.map((k) => num(c, k)).join('') + rares(c);
  let html = '<div class="nl2-in-grid">'
    + rows.map((r) => '<div class="nl2-in-row"><div>' + glEsc(r.label) + '</div><div>' + glEsc(r.status) + '</div><div>' + inT(r.at) + '</div>' + cells(r.cargo) + '</div>').join('');
  if (rows.length > 1) {
    const tot = {};
    for (const r of rows) for (const [k, v] of Object.entries(r.cargo)) tot[k] = (tot[k] || 0) + v;
    html += '<div class="nl2-in-row nl2-in-total"><div>Total</div><div></div><div></div>' + cells(tot) + '</div>';
  }
  html += '</div>';
  if (strip.dataset.sig !== html) { strip.dataset.sig = html; strip.innerHTML = html; }
  const pc = getComputedStyle(hero.parentElement), gap = /flex|grid/.test(pc.display) && parseFloat(pc.rowGap) > 0;
  strip.classList.toggle('nl2-in-gap', !gap);
  if (!inTickTimer) inTickTimer = setTimeout(() => { inTickTimer = 0; NL._kick(); }, 1000);      // the seconds countdown, no reads
}
NL.feature({
  id: 'gl-inbound', set: 'Global', name: 'Inbound fleets',
  desc: 'GL-016 / MO-015: under the banner on a planet\'s Buildings, Shipyard and Research, and on every moon tab (replacing the game\'s Active Missions), one row per fleet bringing resources there, with a total.',
  init() {
    NL.css('gl-inbound', `
      .nl2-inbound{box-sizing:border-box;padding:6px 12px;border-radius:8px;background:rgba(6,14,27,.94);border:1px solid rgba(116,176,232,.2);font-family:Rajdhani,"Exo 2",sans-serif;color:#d9e6f7}
      .nl2-inbound.nl2-in-gap{margin:16px 0}
      .moon-page > section.moon-overview-missions{display:none!important}
      .nl2-in-head{font-size:12.5px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:#7ed4ff;margin-bottom:2px}
      .nl2-in-grid{display:grid;grid-template-columns:minmax(120px,max-content) minmax(90px,max-content) minmax(64px,max-content) repeat(4,minmax(80px,max-content)) minmax(0,1fr);column-gap:0}
      .nl2-in-row{display:contents}
      .nl2-in-row>div{padding:2px 8px;border-top:1px solid rgba(116,176,232,.1);font-size:14px;font-weight:600;line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#e6f0ff;font-variant-numeric:tabular-nums}
      .nl2-in-grid>.nl2-in-row:first-child>div{border-top:0}
      .nl2-in-hdr>div{border-top:0;color:#8aa4c4;font-size:12px;letter-spacing:.4px;text-transform:uppercase}
      .nl2-in-hdr img{width:13px;height:13px;vertical-align:-2px;margin-right:4px}
      .nl2-in-n{text-align:right}
      .nl2-in-n img{width:14px;height:14px;vertical-align:-2px;margin-right:4px}
      .nl2-in-row>div:first-child{padding-left:0}
      .nl2-in-row>div[data-e]{color:#5d708a}
      .nl2-in-total>div[data-e]{color:rgba(251,191,36,.6)}
      .nl2-in-rare{display:flex;gap:10px}
      .nl2-in-res{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}
      .nl2-in-res img{width:14px;height:14px}
      .nl2-in-total>div{margin-top:3px;border-top:1px solid rgba(245,158,11,.45);border-bottom:1px solid rgba(245,158,11,.45);background:rgba(251,191,36,.14);color:#fbbf24;font-weight:700}
      .nl2-in-total>div:first-child{border-left:1px solid rgba(245,158,11,.45);border-radius:5px 0 0 5px;padding-left:6px;margin-left:-6px}
      .nl2-in-total>div:last-child{border-right:1px solid rgba(245,158,11,.45);border-radius:0 5px 5px 0}`);
    NL.onData(/^\/api\/fleet\/missions(\?|$)/, (p, d) => { if (d && Array.isArray(d.missions)) { inData = d; NL._kick(); } });
    NL.onRoute(() => { inKey = ''; });            // each page open counts as fresh
    NL.watch(IN_HEROES, ensureInbound);
  },
});

// ================================================================ GL-018: Low Bio warning on every way Bio leaves the Fleet Bio Supply Planet (David 31 Oct, defaults)
// Ported from old General's G-082, which only watched ship builds and Fleet dispatch, so a Market hub delivery got through. Before one of
// these game requests goes out, if it would leave the supply planet with under 3 days of fleet maintenance, Cancel/Continue asks first.
// Requests (read from the game's code 31 Oct, plain REST, JSON string bodies; snake_case keys, Bio = bio_extract):
//   POST /api/planets/{id}/shipyard/build {shipKey|key, quantity}       Bio per ship from the teed GET /api/planets/{id}/shipyard (rareCosts.bio_extract)
//   POST /api/fleet/dispatch | /api/fleet/moon-dispatch | /api/fleet/market-deliver {sourcePlanetId, cargo}
//   POST /api/moons/{id}/send {sourcePlanetId, cargo}                   planet -> its moon
//   POST /api/market/orders {orderType:'sell', offerResource, offerAmount, planetId?}
//   POST /api/market/limit-orders | /api/market/immediate-orders {side, baseResource, quoteResource, baseAmount, quoteAmount?, planetId?}
// No planetId on a Market order = the current planet. Supply planet and daily cost: GET /api/fleet/supply {supplyPlanet {id, name,
// bioExtract}, dailyCost} (teed, else one read when a Bio spend is checked). Our own Evacuate, Fire Sale and moon sends use NL.rawFetch
// with Blob bodies, so they never pass through here (they have their own confirms).
const BIO_DAYS = 3;
let bioSupply = null, bioPass = 0, shipBio = glLoad('shipBio', {}, 'nxgShipBio');
function gotSupply(j) {
  const sp = j && j.supplyPlanet;
  if (sp && sp.id != null) bioSupply = { id: Number(sp.id), name: String(sp.name || ''), bio: Number(sp.bioExtract) || 0, daily: Number(j.dailyCost) || 0, at: Date.now() };
}
function gotShipBio(j) {
  if (!j || !Array.isArray(j.ships)) return;
  let ch = false;
  for (const x of j.ships) { if (!x || !x.key) continue; const bc = Number(x.rareCosts && x.rareCosts.bio_extract) || 0; if (shipBio[x.key] !== bc) { shipBio[x.key] = bc; ch = true; } }
  if (ch) glSave('shipBio', shipBio);
}
const bioOf = (c) => Object.keys(c && typeof c === 'object' ? c : {}).filter((k) => /bio/i.test(k)).reduce((t, k) => t + (Number(c[k]) || 0), 0);
