const bioLeftText = (days) => { const h = Math.max(0, Math.floor(days * 24)), d = Math.floor(h / 24), r = h % 24; return d + (d === 1 ? ' day ' : ' days ') + r + (r === 1 ? ' hour' : ' hours'); };
