    tdpRoot = NL.h('div', { class: 'nl2-tdp' });
    tdpRoot.innerHTML = '<button type="button" class="nl2-tdp-tab" title="To Do"><span class="nl2-tdp-label">To Do</span></button>'
      + '<div class="nl2-tdp-panel"><div class="nl2-tdp-head"><span>To Do</span><button type="button" class="nl2-tdp-x" title="Collapse">×</button></div><div class="nl2-tdp-body"></div></div>';
    const flip = () => { tdpOpen = !tdpOpen; glSave('todoOpen', tdpOpen); tdpSync(); if (tdpOpen) { const i = tdpRoot.querySelector('.nl2-todo-input'); if (i) i.focus(); } };
    tdpRoot.querySelector('.nl2-tdp-tab').addEventListener('click', flip);
    tdpRoot.querySelector('.nl2-tdp-x').addEventListener('click', flip);
