        + '<td><span class="nxs-dim">—</span></td>'
        + '<td style="color:' + zc + '">' + esc(r.securityZone || '—') + '</td>'
        + '<td>' + (mis || exp === Infinity ? '<span class="nxs-dim">—</span>' : '<span data-cdx data-cd="' + exp + '"></span>') + '</td>'
