  const actName = (m) => m.missionType === 'collect' ? (m.targetFieldId != null ? 'Outpost Collect' : 'Collect') : ACT_NAMES[m.missionType] || String(m.missionType || '?').replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
