        + grp('Nearest Planet', planets.map((n) => '<label><input type="checkbox" data-f="planet" data-v="' + esc(n) + '"' + (f.planet.includes(n) ? ' checked' : '') + '> ' + esc(n) + '</label>').join('') || '<span class="nxs-dim">planets not loaded yet</span>')
