      const need = isEsc(x) && st.sizing ? Math.ceil(rr(x.key) * Math.max(st.sizing.n, 1) / 100) : 0, short = isEsc(x) && rr(x.key) > 0 && (x.qty < Math.ceil(rr(x.key) * (st.sizing ? st.sizing.byMiners : 1) / 100));
